// MGR-2309 item 5: NUMERO COM PONTO OU VIRGULA DECIMAL, sem depender do locale. Um ini ou cfg
// escrito por um processo com locale pt/tr sai "1,000"; o _wtof/atof do locale "C" leria 1 e
// "0,35" viraria 0. Aqui "1,000" = 1.000 e "0,35" = 0.35. So para valores ESCALARES: numa
// lista separada por virgula ("100,50,50") quem separa os itens continua sendo a virgula.
// (Bug #69 do DLSS5 Autopilot, MIT - so a licao; codigo proprio.)
static double NumDecW(const wchar_t* s) {
    if (!s) return 0.0;
    while (*s == L' ' || *s == L'\t') ++s;
    double sinal = 1.0;
    if (*s == L'-') { sinal = -1.0; ++s; } else if (*s == L'+') ++s;
    double v = 0.0; bool dig = false;
    while (*s >= L'0' && *s <= L'9') { v = v * 10.0 + (*s - L'0'); ++s; dig = true; }
    if ((*s == L'.' || *s == L',') && s[1] >= L'0' && s[1] <= L'9') {
        ++s; double f = 0.1;
        while (*s >= L'0' && *s <= L'9') { v += (*s - L'0') * f; f *= 0.1; ++s; dig = true; }
    }
    if (dig && (*s == L'e' || *s == L'E')) {
        const wchar_t* e = s + 1; int se = 1, ex = 0;
        if (*e == L'-') { se = -1; ++e; } else if (*e == L'+') ++e;
        if (*e >= L'0' && *e <= L'9') {
            while (*e >= L'0' && *e <= L'9' && ex < 400) { ex = ex * 10 + (*e - L'0'); ++e; }
            for (int i = 0; i < ex; i++) v = se > 0 ? v * 10.0 : v / 10.0;
        }
    }
    return sinal * v;
}
static double NumDecA(const char* s) {
    if (!s) return 0.0;
    wchar_t w[64]{};
    for (int i = 0; i < 63 && s[i]; i++) w[i] = (wchar_t)(unsigned char)s[i];
    return NumDecW(w);
}
