enum { HK_QUIT = 1, HK_INTERACT = 2, HK_BYPASS = 3,
       HK_QUIT2 = 4, HK_INTERACT2 = 5, HK_BYPASS2 = 6,
       HK_PANEL = 7, HK_PANEL2 = 8 };

