// -------------------------------------------------------------------------------------
// MGR-2309 item 6: CAPTURAR A IMAGEM PROCESSADA. Ideia observada no DLSS 5 Manager (NODIX, codigo
// reservado) - implementacao propria. O print do Windows nao ve a pelicula (WDA_EXCLUDEFROMCAPTURE)
// e mostra o jogo cru; aqui o app grava o PROPRIO backbuffer (a saida da cadeia: rede + ReShade), em
// PNG, numa pasta da pessoa: [ultima] captura_img_pasta, ou Imagens\DLSS5ForAll. Sem popup: o
// resultado vai numa linha de status no painel End e no log. Pedido pelo painel ou pelo atalho
// "capturar" (sem tecla de fabrica). O laco atende depois do Present seguinte; o PNG sai numa thread.
static std::atomic<bool> g_capImgPedida{ false };
static std::mutex        g_capImgMx;
static std::wstring      g_capImgStatus;   // a linha do painel; vazio = nada ainda nesta sessao
static void CapImgStatus(const std::wstring& s) { std::lock_guard<std::mutex> lk(g_capImgMx); g_capImgStatus = s; }
static std::wstring CapImgStatusLer() { std::lock_guard<std::mutex> lk(g_capImgMx); return g_capImgStatus; }
static std::wstring CapImgPasta() {
    std::wstring p = IniGet(L"captura_img_pasta");
    if (p.empty()) {
        wchar_t im[MAX_PATH]{};
        if (SUCCEEDED(SHGetFolderPathW(nullptr, CSIDL_MYPICTURES, nullptr, SHGFP_TYPE_CURRENT, im)) && im[0])
            p = std::wstring(im) + L"\\DLSS5ForAll";
        else
            p = g_exeDir + L"capturas";
    }
    while (!p.empty() && (p.back() == L'\\' || p.back() == L'/')) p.pop_back();
    SHCreateDirectoryExW(nullptr, p.c_str(), nullptr);
    return p + L"\\";
}
static void Refresh();   // definida mais abaixo, neste mesmo namespace
template <class R_>
static void CapturarImagemProcessada(R_& R, bool pontePlacas) {
    std::vector<BYTE> px; UINT w = 0, h = 0;
    const double t0 = (double)GetTickCount64();
    if (!R.CopiarBackbufferBgra(&px, &w, &h) || !w || !h) {
        CapImgStatus(TS(L"captura: FALHOU ao ler o backbuffer", L"capture: FAILED to read the backbuffer"));
        Log("captura de imagem: FALHOU ao ler o backbuffer da pelicula");
        return;
    }
    SYSTEMTIME st{}; GetLocalTime(&st);
    wchar_t nome[96];
    _snwprintf(nome, 96, L"DLSS5ForAll_%04u%02u%02u_%02u%02u%02u_%03u.png", st.wYear, st.wMonth, st.wDay,
               st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
    nome[95] = 0;
    const std::wstring caminho = CapImgPasta() + nome;
    CapImgStatus(TS(L"captura: salvando ", L"capture: saving ") + std::wstring(nome) + L"…");
    Refresh();   // thread do laco, como os outros chamadores
    Log("captura de imagem: %ux%u lidos em %.0f ms%s -> %s", w, h, (double)GetTickCount64() - t0,
        pontePlacas ? " (com a ponte entre placas a tela mostra o apresentador; este e o quadro da cadeia, antes da interpolacao)" : "",
        U8(caminho).c_str());
    std::thread([px = std::move(px), w, h, caminho, nome = std::wstring(nome)]() mutable {
        bool ok = false;
        {
            Gdiplus::Bitmap bmp((INT)w, (INT)h, (INT)(w * 4), PixelFormat32bppARGB, px.data());
            CLSID png{};
            if (Hud::EncoderClsid(L"image/png", &png) >= 0)
                ok = bmp.Save(caminho.c_str(), &png, nullptr) == Gdiplus::Ok;
        }
        CapImgStatus(ok ? TS(L"captura salva: ", L"capture saved: ") + nome
                        : TS(L"captura: FALHOU ao gravar ", L"capture: FAILED to write ") + nome);
        Log("captura de imagem: %s %s", ok ? "salva" : "FALHOU ao gravar", U8(caminho).c_str());
    }).detach();
}
