// ------------------------------------------ R1: VIGIA DE SAUDE DO NATIVO (16/09/2026)
// Com a ponte ativa, o laco confere a cada 1 s cinco sinais de que o Nativo nao esta servindo:
// 1 a DLL nao viu Present em 10 s (Vulkan/OpenGL), 2 in_fence nao chegou 2x seguidas (tela
// preta), 3 a saida do app parada com o jogo mudando (a trava da DLL publica), 4 o device do
// app removido, 5 o jogo abaixo de 50 % do fps de antes por 5 s. Reacao (regra do dono):
// 2/3/4 na 1a vez reabrem o app no NATIVO ("Reiniciando o DLSS 5…"); de novo antes de 5 min
// estaveis, reabrem em UNIVERSAL; 1 e 5 vao direto ao Universal. Tudo pela reabertura com a
// mesma fonte. O estado atravessa o processo pela linha de comando (ArgsDeReabertura) e cada
// erro fica no log, no perfil do jogo e no erros-nativo.log. Limite global: 3 reaberturas
// automaticas em 2 min (HDR, upstream, vigia); estourou = fica em Universal ate a pessoa
// trocar de modo. Troca pedida pela pessoa nao conta e zera tudo.
enum { VN_CARTAZ_UNIVERSAL = 1, VN_CARTAZ_REINICIANDO, VN_CARTAZ_INDISPONIVEL };
enum { VN_DICA_AUTO = 1, VN_DICA_SEM_PRESENT, VN_DICA_PAROU, VN_DICA_DEVICE, VN_DICA_LENTO,
       VN_DICA_DUAS_VEZES, VN_DICA_RESET };
struct VigiaNativo {
    int       tentativas = 0;          // resets no Nativo ja feitos nesta fonte (--nativo-tentativas)
    long long falhaEm = 0;             // hora unix do ultimo (--nativo-falha-em)
    int       dica = 0;                // VN_DICA_*: o ultimo motivo nesta fonte (--nativo-dica)
    int       cartaz = 0;              // VN_CARTAZ_*: a copia nova mostra uma vez (--nativo-cartaz)
    std::vector<long long> reabAuto;   // horas unix das reaberturas automaticas recentes (--reab-auto)
    bool      limite = false;          // o limite global estourou nesta copia
    int       falhasPerfil = 0;        // [perfil:<exe>] nativo_falhas, lido no arranque
    int          codigo = 0;           // X-CODIGOS: Msg::Codigo do ultimo motivo nesta fonte (--nativo-codigo)
    std::wstring ocorr;                // X-CODIGOS: id da ocorrencia dele (--nativo-ocorr); vai no rodape do cartaz
};
static VigiaNativo g_vn;
static std::wstring g_modoAbertura;   // --modo desta abertura; vai adiante em toda reabertura que mantem a fonte
static bool g_selCamposNativo = false; // E2: o seletor mostrou os campos do Nativo (sem resolucao do jogo)
// FLUIDEZ1 (22/09/2026): esta abertura e FONTE DE CAPTURA (monitor, video, camera, janela) e
// nao jogo (ponte injetada, Nativo, Upstream)? Decidido uma vez no arranque, junto com o motor
// padrao - ver o bloco "EM FONTE DE CAPTURA O MOTOR PADRAO E O PROPRIO". O painel le daqui
// para a dica do chip do motor dizer a verdade desta sessao em vez de um texto fixo.
static bool g_fonteCaptura = false;
static long long AgoraUnix() { return (long long)time(nullptr); }

static std::wstring VnCartaz(int c) {
    switch (c) {
    case VN_CARTAZ_UNIVERSAL:    return TS(L"Modo Universal ativado", L"Universal mode on");
    case VN_CARTAZ_REINICIANDO:  return TS(L"Reiniciando o DLSS 5…", L"Restarting DLSS 5…");
    case VN_CARTAZ_INDISPONIVEL: return TS(L"Modo Nativo indisponível neste jogo", L"Native mode unavailable in this game");
    }
    return L"";
}
static std::wstring VnDica(int d) {
    switch (d) {
    case VN_DICA_AUTO: return TS(L"O modo Nativo não funcionou bem neste jogo e trocamos sozinhos para o Universal. O seu jogo não foi afetado.",
                                 L"Native mode didn't work well in this game, so we switched to Universal for you. Your game was not affected.");
    case VN_DICA_SEM_PRESENT: return TS(L"Este jogo usa uma tecnologia gráfica que o modo Nativo ainda não suporta.",
                                        L"This game uses graphics technology that Native mode doesn't support yet.");
    case VN_DICA_PAROU: return TS(L"A imagem do modo Nativo parou de atualizar. Trocamos para o Universal para você continuar jogando.",
                                  L"Native mode's image stopped updating. We switched to Universal so you can keep playing.");
    case VN_DICA_DEVICE: return TS(L"A placa de vídeo teve uma falha momentânea. Reabrimos o DLSS 5 automaticamente.",
                                   L"Your graphics card had a momentary hiccup. We reopened DLSS 5 automatically.");
    case VN_DICA_LENTO: return TS(L"O modo Nativo estava deixando este jogo mais lento. O Universal vai render melhor aqui.",
                                  L"Native mode was slowing this game down. Universal will run better here.");
    case VN_DICA_DUAS_VEZES: return TS(L"Tentamos duas vezes e não funcionou. Você pode continuar no Universal.",
                                       L"We tried twice and it didn't work. You can keep playing in Universal.");
    case VN_DICA_RESET: return TS(L"A imagem parou de atualizar e reiniciamos o DLSS 5. O seu jogo não foi afetado.",
                                  L"The image stopped updating, so we restarted DLSS 5. Your game was not affected.");
    }
    return L"";
}

// O limite global: no maximo 3 reaberturas automaticas em 2 min, somando todos os motivos.
static bool VnReaberturaPode() {
    const long long agora = AgoraUnix();
    std::vector<long long> v;
    for (long long t : g_vn.reabAuto) if (agora - t < 120) v.push_back(t);
    g_vn.reabAuto = v;
    return !g_vn.limite && g_vn.reabAuto.size() < 3;
}
static void VnReaberturaConta() { g_vn.reabAuto.push_back(AgoraUnix()); }

// O que a copia nova precisa saber (so o que nao e padrao). ArgsDeReabertura anexa.
static std::wstring VnArgs() {
    std::wstring s;
    // o --modo da abertura atravessa as reaberturas automaticas (HDR, tamanho interno): sem isto
    // um Nativo ligado por F8 com o ini em Universal nao voltaria na copia nova. Quem acrescenta
    // outro --modo depois vence (o ultimo da linha e o que vale).
    if (!g_modoAbertura.empty()) s += L" --modo " + g_modoAbertura;
    if (g_vn.tentativas > 0) s += L" --nativo-tentativas " + std::to_wstring(g_vn.tentativas);
    if (g_vn.falhaEm > 0)    s += L" --nativo-falha-em " + std::to_wstring(g_vn.falhaEm);
    if (g_vn.dica > 0)       s += L" --nativo-dica " + std::to_wstring(g_vn.dica);
    if (g_vn.codigo > 0)     s += L" --nativo-codigo " + std::to_wstring(g_vn.codigo);
    if (!g_vn.ocorr.empty()) s += L" --nativo-ocorr " + g_vn.ocorr;
    if (!g_vn.reabAuto.empty()) {
        s += L" --reab-auto ";
        for (size_t i = 0; i < g_vn.reabAuto.size(); i++) s += (i ? L"," : L"") + std::to_wstring(g_vn.reabAuto[i]);
    }
    return s;
}

// X-CE-1 (X-CODIGOS-ERRO §5.3, 18/09/2026): O ERROS-NATIVO.LOG TEM UM SO JEITO DE ESCREVER.
// Ate aqui o app RE-ESCREVIA o arquivo inteiro cortando em 200 linhas, enquanto a DLL dentro do
// jogo (ponte_cliente.cpp, EstouroRegistrar) so ANEXA (FILE_APPEND_DATA): um bloco de estouro
// que a DLL acabara de gravar podia ser apagado pelo truncamento do app segundos depois -
// justamente o bloco mais valioso para o relato (D5-NAT-206). Agora os dois ANEXAM, com o
// mesmo FILE_APPEND_DATA (atomico por escrita), e a rotacao e por TAMANHO: passando de
// kErrosNativoMax o app renomeia para erros-nativo.1.log (a geracao anterior sai) e recomeca.
// Se a DLL estiver com o arquivo aberto naquele instante, o rename falha e a rotacao fica para
// a proxima vez - nunca se perde registro, no maximo adia-se a rotacao.
static const ULONGLONG kErrosNativoMax = 256 * 1024;
static void ErrosNativoAnexar(const std::string& linha) {
    const std::wstring arq = g_exeDir + L"erros-nativo.log";
    WIN32_FILE_ATTRIBUTE_DATA fa{};
    if (GetFileAttributesExW(arq.c_str(), GetFileExInfoStandard, &fa)) {
        const ULONGLONG tam = ((ULONGLONG)fa.nFileSizeHigh << 32) | fa.nFileSizeLow;
        if (tam > kErrosNativoMax) {
            const std::wstring velho = g_exeDir + L"erros-nativo.1.log";
            if (MoveFileExW(arq.c_str(), velho.c_str(), MOVEFILE_REPLACE_EXISTING))
                Log("erros-nativo.log: passou de %llu KB - rodado para erros-nativo.1.log", (unsigned long long)(tam / 1024));
        }
    }
    HANDLE h = CreateFileW(arq.c_str(), FILE_APPEND_DATA, FILE_SHARE_READ | FILE_SHARE_WRITE,
                           nullptr, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (h == INVALID_HANDLE_VALUE) return;
    const std::string l = linha + "\r\n";
    DWORD escritos = 0;
    WriteFile(h, l.data(), (DWORD)l.size(), &escritos, nullptr);
    CloseHandle(h);
}

// REGISTRA UM ERRO do Nativo em tres lugares: a linha unica no log (com as ultimas linhas
// da DLL e do feed), o perfil do jogo no ini (sobrevive entre sessoes) e o erros-nativo.log ao
// lado do exe (so acrescenta, roda por tamanho; vai no relato do Ctrl+F12).
// X-CODIGOS: o sinal vira CODIGO do catalogo (Msg::DoVigia, pre-identificacao exata) e cada
// registro ganha um id de ocorrencia; devolve o id, que o cartaz leva no rodape. A string
// tecnica `desc` continua indo LITERAL para todos os arquivos (linha `detalhe|`).
static std::string VnRegistrar(int sinal, const char* desc, const char* modo, int tentativa, const char* acao, DWORD pidJogo) {
    const std::string exe = g_perfilExe.empty() ? std::string("desconhecido") : U8(g_perfilExe);
    const Msg::Codigo cod = Msg::DoVigia(sinal);
    char extra[400];
    snprintf(extra, sizeof(extra), "sinal=%d jogo=%s modo=%s tentativa=%d acao=%s", sinal, exe.c_str(), modo, tentativa, acao);
    const std::string ocorr = Codigos::Registrar(cod, desc, extra);
    char linha[640];
    snprintf(linha, sizeof(linha), "vigia: erro nativo sinal=%d (%s) jogo=%s modo=%s tentativa=%d acao=%s",
             sinal, desc, exe.c_str(), modo, tentativa, acao);
    Log("%s", linha);
    // as ultimas linhas que contam a historia, da DLL (no %TEMP%) e do feed
    const auto ultimas = [](const std::string& t, int n, const char* pular) {
        std::vector<std::string> ls; std::string cur;
        for (char ch : t) { if (ch == '\n') { if (!cur.empty() && (!pular || cur.find(pular) == std::string::npos)) ls.push_back(cur); cur.clear(); }
                            else if (ch != '\r') cur += ch; }
        if (!cur.empty()) ls.push_back(cur);
        if ((int)ls.size() > n) ls.erase(ls.begin(), ls.end() - n);
        return ls;
    };
    wchar_t tmp[MAX_PATH] = L""; GetTempPathW(MAX_PATH, tmp);
    for (const auto& l : ultimas(TailArquivo(std::wstring(tmp) + L"dlss5-ponte." + std::to_wstring(pidJogo) + L".log", 4096), 3, "300 quadros"))
        Log("vigia:   dll| %s", l.c_str());
    for (const auto& l : ultimas(TailArquivo(g_exeDir + L"dlss5-feed.log", 8192), 3, nullptr))
        Log("vigia:   feed| %s", l.c_str());

    SYSTEMTIME st{}; GetLocalTime(&st);
    wchar_t quando[40];
    _snwprintf(quando, 40, L"%04u-%02u-%02u %02u:%02u:%02u", st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond); quando[39] = 0;
    if (!g_perfilExe.empty()) {
        const std::wstring sec = L"perfil:" + g_perfilExe;
        const int n = (int)GetPrivateProfileIntW(sec.c_str(), L"nativo_falhas", 0, IniPath().c_str()) + 1;
        wchar_t motivo[200];
        _snwprintf(motivo, 200, L"%hs sinal %d (%hs)", Msg::CodigoStr(cod), sinal, desc); motivo[199] = 0;
        WritePrivateProfileStringW(sec.c_str(), L"nativo_falhas", std::to_wstring(n).c_str(), IniPath().c_str());
        WritePrivateProfileStringW(sec.c_str(), L"nativo_ultima_falha", quando, IniPath().c_str());
        WritePrivateProfileStringW(sec.c_str(), L"nativo_ultimo_motivo", motivo, IniPath().c_str());
        g_vn.falhasPerfil = n;
    }
    ErrosNativoAnexar(U8(quando) + " " + Msg::CodigoStr(cod) + " ocorr=" + ocorr + " " + linha);
    return ocorr;
}

// I7 (18/09/2026): AS MARCAS DO UPSTREAM POR JOGO, no mesmo [perfil:<exe>] do nativo_falhas.
//   upstream_ok=1       o Upstream ja passou quadro por aqui neste jogo (gravado no primeiro quadro
//                       processado). Com a marca, o upscaler parar porque o jogador o desligou no
//                       menu e PAUSA (nao conta como falha); sem a marca, a sessao que negocia e nao
//                       manda quadro conta como falha.
//   upstream_falhas=N   quedas reais (orcamento estourado, DLSS SR falhando, pipe fechado com o jogo
//                       vivo, sessao sem quadro). Na segunda o chip some e o Automatico nem tenta;
//                       escolher Upstream a mao continua tentando (e o jeito de forcar de novo).
// Uma queda real apaga o upstream_ok. E um degrau A MAIS na cadeia A8/A9 (Upstream -> Nativo ->
// Universal), com o mesmo perfil e o mesmo erros-nativo.log - nao um segundo mecanismo.
static void UpstreamLerMarcas() {
    g_upstreamFalhas = 0; g_upstreamOk = false;
    if (g_perfilExe.empty()) return;
    const std::wstring sec = L"perfil:" + g_perfilExe;
    g_upstreamFalhas = (int)GetPrivateProfileIntW(sec.c_str(), L"upstream_falhas", 0, IniPath().c_str());
    g_upstreamOk     = GetPrivateProfileIntW(sec.c_str(), L"upstream_ok", 0, IniPath().c_str()) != 0;
    if (g_upstreamFalhas > 0 || g_upstreamOk)
        Log("upstream: marcas do jogo (perfil): upstream_ok=%d upstream_falhas=%d%s", (int)g_upstreamOk, g_upstreamFalhas,
            g_upstreamFalhas >= 2 ? " - o Upstream nao e mais oferecido aqui (so a mao do jogador)" : "");
}
static void UpstreamMarcarOk() {
    if (g_upstreamOk) return;
    g_upstreamOk = true;
    if (g_perfilExe.empty()) return;
    WritePrivateProfileStringW((L"perfil:" + g_perfilExe).c_str(), L"upstream_ok", L"1", IniPath().c_str());
    Log("upstream: funcionou neste jogo - [perfil:%s] upstream_ok=1", U8(g_perfilExe).c_str());
}
// X-CODIGOS: a string de motivo do Upstream vira codigo (Msg::DoUpstream, por substring; o que
// nao casa e D5-UPS-999 com a string crua no log). Devolve o id da ocorrencia para o rodape.
static std::string UpstreamRegistrarFalha(const char* motivo, DWORD pidJogo, Msg::Codigo* codOut = nullptr) {
    const std::string exe = g_perfilExe.empty() ? std::string("desconhecido") : U8(g_perfilExe);
    g_upstreamOk = false;
    g_upstreamFalhas++;
    const Msg::Codigo cod = Msg::DoUpstream(motivo);
    if (codOut) *codOut = cod;
    char extra[300];
    snprintf(extra, sizeof(extra), "jogo=%s modo=%s falhas=%d acao=%s", exe.c_str(), NomeModoProc(g_modoEscolha), g_upstreamFalhas,
             g_upstreamFalhas >= 2 ? "nao-oferecer" : "seguir-nativo");
    const std::string ocorr = Codigos::Registrar(cod, motivo, extra);
    char linha[400];
    snprintf(linha, sizeof(linha), "vigia: erro upstream (%s) jogo=%s modo=%s falhas=%d acao=%s",
             motivo, exe.c_str(), NomeModoProc(g_modoEscolha), g_upstreamFalhas,
             g_upstreamFalhas >= 2 ? "nao-oferecer" : "seguir-nativo");
    Log("%s", linha);
    wchar_t tmp[MAX_PATH] = L""; GetTempPathW(MAX_PATH, tmp);
    const std::string dll = TailArquivo(std::wstring(tmp) + L"dlss5-ponte." + std::to_wstring(pidJogo) + L".log", 2048);
    { size_t p = dll.size(), n = 0; while (p > 0 && n < 3) { p = dll.find_last_of('\n', p - 1); if (p == std::string::npos) { p = 0; break; } n++; }
      if (!dll.empty()) Log("vigia:   dll| %s", dll.substr(p).c_str()); }
    SYSTEMTIME st{}; GetLocalTime(&st);
    wchar_t quando[40];
    _snwprintf(quando, 40, L"%04u-%02u-%02u %02u:%02u:%02u", st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond); quando[39] = 0;
    if (!g_perfilExe.empty()) {
        const std::wstring sec = L"perfil:" + g_perfilExe;
        WritePrivateProfileStringW(sec.c_str(), L"upstream_falhas", std::to_wstring(g_upstreamFalhas).c_str(), IniPath().c_str());
        WritePrivateProfileStringW(sec.c_str(), L"upstream_ok", nullptr, IniPath().c_str());
    }
    // o mesmo erros-nativo.log do R1 (X-CE-1: um so escritor, so acrescenta)
    ErrosNativoAnexar(U8(quando) + " " + Msg::CodigoStr(cod) + " ocorr=" + ocorr + " " + linha);
    return ocorr;
}
// "So a mao do jogador muda": trocar o modo a mao zera as marcas de FALHA do jogo (Upstream e
// Nativo), para ele ter uma chance limpa. O upstream_ok fica (e marca de sucesso).
static void ModoZerarFalhas(const char* quem) {
    g_upstreamFalhas = 0; g_vn.falhasPerfil = 0;
    if (g_perfilExe.empty()) return;
    const std::wstring sec = L"perfil:" + g_perfilExe;
    // no seletor os contadores em memoria ainda nao foram lidos: a verdade e o ini
    const bool tinha = GetPrivateProfileIntW(sec.c_str(), L"upstream_falhas", 0, IniPath().c_str()) > 0 ||
                       GetPrivateProfileIntW(sec.c_str(), L"nativo_falhas", 0, IniPath().c_str()) > 0;
    if (!tinha) return;
    for (const wchar_t* k : { L"upstream_falhas", L"nativo_falhas", L"nativo_ultima_falha", L"nativo_ultimo_motivo" })
        WritePrivateProfileStringW(sec.c_str(), k, nullptr, IniPath().c_str());
    Log("modo: troca a mao (%s) - marcas de falha de [perfil:%s] zeradas (upstream_falhas, nativo_falhas)", quem, U8(g_perfilExe).c_str());
}

