// Por que o chip Nativo esta esmaecido - vai SO na dica (regra do produto: pouco texto na tela).
static std::wstring MotivoNativo() {
    switch (AntiCheatAtivo() ? (g_antiCheatAuto ? 2 : 1) : g_nativoVeto) {
    case 1: return TS(L"Indisponível: o Modo anti-cheat está ligado (tela de escolha da fonte).",
                      L"Unavailable: Anti-cheat mode is on (source selection screen).");
    case 2: return TS(L"Indisponível: anti-cheat detectado nesta fonte (",
                      L"Unavailable: anti-cheat detected in this source (") + g_antiCheatProduto + L").";
    case 3: return TS(L"Indisponível: o jogo é de 32 bits (o Nativo pede 64 bits).",
                      L"Unavailable: the game is 32-bit (Native needs 64-bit).");
    // sec. 22: a tecla de integrar de AGORA (a pessoa pode ter trocado ou tirado o F8 em Atalhos)
    case 4: return Msg::TrocarF8(TS(L"Indisponível: a integração falhou nesta fonte (veja o log). F8 tenta de novo.",
                      L"Unavailable: integration failed in this source (see the log). Press F8 to retry."));
    case 5: return Msg::TrocarF8(TS(L"Indisponível: o jogo não respondeu à integração (veja o log). F8 tenta de novo.",
                      L"Unavailable: the game did not answer the integration (see the log). Press F8 to retry."));
    case 6: {   // R1: a vigia de saude tirou o Nativo desta fonte (X-CODIGOS: o codigo vai junto, na dica)
        std::wstring d = VnDica(g_vn.dica);
        if (g_vn.codigo > 0) d += L"  [" + Codigos::Rodape((Msg::Codigo)g_vn.codigo, U8(g_vn.ocorr)) + L"]";
        return d;
    }
    }
    return L"";
}

// I6 (18/09/2026): o jogo capturado tem um upscaler que a DLL engancha (DLSS, FSR 2/3.1/SDK 2.x,
// XeSS)? Decide se o chip Upstream existe no card Modo. Medido no processo (modulos carregados e
// pasta do exe, Sel::GanchoDoProcesso) a cada 5 s: um jogo Unreal carrega o upscaler tarde.
// Uma sessao upstream ja vista nesta abertura vale como prova sem medir.
static bool UpstreamNoJogo() {
    static DWORD pid = 0; static ULONGLONG quando = 0; static bool tem = false;
    if (g_upstreamRodou || FonteUpstream::SessaoNegociada()) return true;
    const DWORD p = (DWORD)g_hud.pidAlvo;
    if (p == 0) return false;
    const ULONGLONG agora = GetTickCount64();
    if (p != pid || agora - quando >= 5000) {
        const wchar_t* gk = Sel::GanchoDoProcesso(p);
        if (p != pid || (gk != nullptr) != tem)
            Log("painel: chip Upstream %s (pid %lu%s%ls)", gk ? "visivel" : "fora", (unsigned long)p, gk ? ", gancho " : ", sem DLSS/FSR/XeSS com gancho", gk ? gk : L"");
        pid = p; quando = agora; tem = gk != nullptr;
    }
    return tem;
}

// D1 (16/09/2026): o que nao funciona naquele jogo ou modo SOME do painel. Estas duas decidem
// se os cards "DLSS do jogo" e "Frame generation" existem; Render e AssinaturaAltura usam as duas.
//
// "DLSS do jogo": so com a ponte ativa E a DLL tendo confirmado NGX (.ngx-estado ngx=1) ou o
// hook SR tendo subido a sessao DLSS SR do app (0x200, o mesmo que o .sr-estado ativa=1). Preso
// por pid: um SR que cai por um instante nao faz o card piscar.
static bool CardDlssJogoVisivel() {
    static DWORD visto = 0;
    if (!g_hud.modoIntegrado || g_hud.integrando || g_dlssJogoPid == 0) return false;
    if (visto != g_dlssJogoPid && ((g_dlssJogo.lido && g_dlssJogo.ngx) || FonteUpstream::SessaoSr())) {
        visto = g_dlssJogoPid;
        Log("painel: card DLSS do jogo visivel (pid %lu, %s)", (unsigned long)visto, g_dlssJogo.ngx ? "NGX confirmado" : "DLSS SR do app");
    }
    return visto == g_dlssJogoPid;
}

// A API do jogo na ponte: 12, 11 ou 0 (ainda nao sabe). D6: vem da chave jogo_api do .ngx-estado,
// que a DLL publica sempre desde o 1o Present (antes lia o log da DLL). Log uma vez por pid.
static int ApiJogoPonte() {
    static DWORD pid = 0; static int api = 0;
    if (g_dlssJogoPid == 0) return 0;
    if (pid != g_dlssJogoPid) { pid = g_dlssJogoPid; api = 0; }
    if (api == 0 && g_dlssJogo.lido) {
        api = g_dlssJogo.jogoApi == "D3D12" ? 12 : g_dlssJogo.jogoApi == "D3D11" ? 11 : 0;
        if (api) Log("painel: jogo D3D%d na ponte (jogo_api) - card Frame generation %s", api, api == 12 ? "visivel" : "fora");
    }
    return api;
}

// "Frame generation": so no Nativo (ponte ativa) e em jogo D3D12.
static bool CardFgVisivel() {
    return g_hud.modoIntegrado && !g_hud.integrando && ApiJogoPonte() == 12;
}

