// Mantem o cartao dentro da area util do monitor onde ele esta. Vale para a posicao
// gravada tambem: um ini de dois monitores aberto com um so nao pode esconder o painel.
static void ClamparNaTela(POINT& p, int W, int H) {
    const POINT centro{ p.x + W / 2, p.y + H / 2 };
    MONITORINFO mi{ sizeof(mi) };
    if (!GetMonitorInfoW(MonitorFromPoint(centro, MONITOR_DEFAULTTONEAREST), &mi)) return;
    if (p.x + W > mi.rcWork.right)  p.x = mi.rcWork.right - W;
    if (p.y + H > mi.rcWork.bottom) p.y = mi.rcWork.bottom - H;
    if (p.x < mi.rcWork.left) p.x = mi.rcWork.left;
    if (p.y < mi.rcWork.top)  p.y = mi.rcWork.top;
}
// Rodada 24 (pedido do dono): a posicao SALVA de uma sessao anterior so vale se coubesse
// INTEIRA em algum monitor de AGORA (nao clampa, nao arredonda - ou cabe, ou nao serve).
// Diferente do ClamparNaTela acima (que so evita a janela sumir ENQUANTO a pessoa arrasta,
// ajustando o que nao coube): aqui a resposta e binaria, e so roda UMA VEZ, na abertura -
// depois disso, arrastar de novo vale a escolha nova da pessoa, clampada como sempre.
static bool CabeEmAlgumMonitor(const POINT& p, int W, int H) {
    struct Ctx { RECT alvo; bool cabe; } ctx{ { p.x, p.y, p.x + W, p.y + H }, false };
    EnumDisplayMonitors(nullptr, nullptr, [](HMONITOR mon, HDC, LPRECT, LPARAM lp) -> BOOL {
        Ctx* c = (Ctx*)lp;
        MONITORINFO mi{}; mi.cbSize = sizeof(mi);   // sem o aviso de -Wmissing-field-initializers
        if (!GetMonitorInfoW(mon, &mi)) return TRUE;
        const RECT& w = mi.rcWork;
        if (c->alvo.left >= w.left && c->alvo.top >= w.top && c->alvo.right <= w.right && c->alvo.bottom <= w.bottom) {
            c->cabe = true;
            return FALSE;   // achou - nao precisa olhar os outros monitores
        }
        return TRUE;
    }, (LPARAM)&ctx);
    return ctx.cabe;
}
